# ╔═╡ b6c511c8-918d-432c-9756-9641176ff652
md"""
## Model to predict Earth's surface temperature
"""

# ╔═╡ e8a5cf48-f647-4fb3-8c0a-4eae97d03e02
md"""

The goal is to predict the evolution of the average surface temperature of the Earth as a function of external forcing, like the atmospheric concentration of $CO_2$. Let us start by introducing some notation: 

``T=T(t)`` is the Earth's average surface temperature as a function of time $t$ 

Initially $t=0$, $T(0)=T_0$

We look for an equation of the form:

``dT/dt = f(t)``

where ``f(t)`` represents the external forcing which acts to change the Earth's temperature ``T(t)``
"""

# ╔═╡ 8516277a-2c98-4390-90bb-3a2276ef54e4
md"""
---

#### Solving an ODE of the form ``dT/dt=f(T,p,t)`` in Julia

0. Define f(T,p,t)
1. ODEProblem(f, T₀, time_span, parameters)
2. solve
3. plot etc
"""

# ╔═╡ a28f7886-3237-49d0-9c41-84f52aaff2ea
md"""
---

### Earth energy budget
"""

# ╔═╡ 739e914a-9760-4a84-a860-7acadddfc21f
md"""

The energy (heat) budget of a planet without atmosphere is given by the simple equation:

$\begin{align}
\text{\color{brown}{change in temperature}} = & + \text{\color{red}{heating from the Sun's rays}} \newline
& - \text{\color{red}{reflected solar radiation}}\newline
& - \text{\color{blue}{outgoing thermal radiation}}
\end{align}$

where each of these is interpreted as an average over the entire globe.


"""

# ╔═╡ 3a66b385-737e-49e4-b30d-56b055b7bf44
html"""
<figure>
<img src="data:image/jpeg;base64," style="width: 100%; max-width: 680px;" alt="Earth's energy budget">
<figcaption>Earth's energy budget. <a href="https://commons.wikimedia.org/wiki/File:The-NASA-Earth%27s-Energy-Budget-Poster-Radiant-Energy-System-satellite-infrared-radiation-fluxes.jpg">NASA</a>, public domain (image embedded in the notebook).</figcaption>
</figure>
"""

# ╔═╡ 4b074c56-dc58-4c9c-ae64-7b9ba8d92c20
md"""
---
#### Start with solar heating only

"""

# ╔═╡ ebfeb0b0-d29e-4244-a0e3-a7185f3c8124
md"""

``dT/dt = a ``
$(html"<br>") Solution: ``T(t) = a t + T_0``

"""

# ╔═╡ de443120-f6e1-4fa4-a915-2a316e7fab9d
S_0 = 1366/4; # solar insolation [W/m^2]  (energy per unit time per unit area)

# ╔═╡ 81630f00-2bde-48f2-b8a6-472c732ff8da
C = 355.; # atmosphere and upper-ocean heat capacity [Wyr/m^2/°K]

# ╔═╡ 2251e66d-0188-477c-acf2-14ed3c51e85f
a = S_0/C;

# ╔═╡ b38f98a0-fee8-4746-a136-247e78230f34
begin
	temp₀ = 0.0;  # absolute zero [K]
	timespan = 1000.;
end

# ╔═╡ a1683297-6ad5-4143-bb3a-ff0b6b52ace4
m1 = ODEProblem( (temp, p, t)-> a, temp₀,  (0, timespan) )

# ╔═╡ 3785b312-4228-44e5-992b-90cd23f2bac2
let
	fig, ax = temperature_figure("Absorbing solar radiation only"; ylims = (-300, 400))
	temperature_line!(ax, solve(m1))
	reference_line!(ax, temp₀; label = "initial: $(temp₀) K", color = palette.initial)
	reference_line!(ax, K₀ + 15; label = "observed today ≈ 15 °C",
	                color = palette.observed, linestyle = :dot)
	side_legend!(fig, ax)
	fig
end

# ╔═╡ 4bf60f27-8db5-42c1-83d8-750bec2060e5
md"""
---

#### Adding reflection of solar radiation
\
``dT/dt = (1 - \alpha)a ``$(html"<br>") Solution: ``T(t) = (1 -\alpha) a t + T_0``

where $\alpha$ is called albedo and equal to 30\%.

"""

# ╔═╡ 67153542-28cb-4d8a-ae86-b13be5f84557
alpha = 0.3; # albedo, or planetary reflectivity [unitless]

# ╔═╡ ad973c4b-0162-48fb-b5e0-342d772af800
m2 = ODEProblem( (temp, p, t)-> a * (1-alpha), temp₀,  (0, timespan) )

# ╔═╡ 54801ddc-c1a6-4e82-8264-08c2205d18ed
let
	fig, ax = temperature_figure("Absorbing and reflecting solar radiation"; ylims = (-300, 400))
	temperature_line!(ax, solve(m2))
	reference_line!(ax, temp₀; label = "initial: $(temp₀) K", color = palette.initial)
	reference_line!(ax, K₀ + 15; label = "observed today ≈ 15 °C",
	                color = palette.observed, linestyle = :dot)
	side_legend!(fig, ax)
	fig
end

# ╔═╡ e2799d05-36a7-4547-8663-90708ce01ce8
md"""
---

#### Adding radiative cooling
\
``dT/dt = (1-\alpha) a - b T^4 ``$(html"<br>")

At long times the temperature reaches a stable value, where absorbed and emitted radiation balance:
``T_{eq} = \left(\frac{(1-\alpha)a }{b}\right)^{1/4}``

"""

# ╔═╡ 3ba79372-aa57-49a8-9d50-146ef8f7d0b3
sigma = 5.670374419e-8; # Stefan-Boltzmann constant [W/m^2/K^4]

# ╔═╡ 17800b4d-a879-4270-b39d-c44901f46391
b = sigma/C;

# ╔═╡ 578a80ad-fcf1-4d5c-81e5-205113bbf78d
m3 = ODEProblem( (temp, p, t)-> a * (1-alpha) - b*temp^4, temp₀,  (0, timespan) )

# ╔═╡ 7af3719c-bf0c-4502-a098-66f797f1b6ea
let
	T_eq = ((1 - alpha) * a / b)^(1/4)
	fig, ax = temperature_figure("Including outgoing thermal radiation"; ylims = (-300, 20))
	temperature_line!(ax, solve(m3))
	reference_line!(ax, temp₀; label = "initial: $(temp₀) K", color = palette.initial)
	reference_line!(ax, T_eq; label = "equilibrium: $(celsius(T_eq)) °C",
	                color = palette.equilibrium)
	reference_line!(ax, K₀ + 15; label = "observed today ≈ 15 °C",
	                color = palette.observed, linestyle = :dot)
	side_legend!(fig, ax)
	fig
end

# ╔═╡ 9fca410f-87bd-405d-8336-3ae109ee60f9
md"""
---

#### Adding an atmosphere
\
``dT/dt = (1-\alpha) a - (1-\epsilon/2)b T^4 ``$(html"<br>")

At long times the temperature reaches a stable value:
``T_{eq} = \left(\frac{(1-\alpha)a }{(1-\epsilon/2)b}\right)^{1/4}``

Move the slider to change the atmosphere's emissivity ``\epsilon``.
"""

# ╔═╡ de777b52-8ff7-4fc9-bdbc-17d64abf8926
T₀=273.15-18;

# ╔═╡ ae54e5a6-f4ab-4196-845e-612e7c7ebb5c
md"""

epsilon = $(@bind epsilon Slider(0:.01:1, show_value=true, default=0) )

"""

# ╔═╡ 3aa13ecd-9d4a-4b41-b15f-f85e2b8f8bf6
m4 = ODEProblem( (temp, p, t)-> a * (1-alpha) - (1-epsilon/2)*b*temp^4, T₀,  (0, timespan) )

# ╔═╡ 2d3740ae-bbeb-49a5-a51e-0b5079e68592
let
	T_eq = ((1 - alpha) * a / ((1 - epsilon / 2) * b))^(1/4)
	fig, ax = temperature_figure("With an atmosphere of emissivity ε = $(epsilon)";
	                             ylims = (-30, 35))
	temperature_line!(ax, solve(m4))
	reference_line!(ax, T₀; label = "initial: $(celsius(T₀)) °C", color = palette.initial)
	reference_line!(ax, T_eq; label = "equilibrium: $(celsius(T_eq)) °C",
	                color = palette.equilibrium)
	reference_line!(ax, K₀ + 15; label = "observed today ≈ 15 °C",
	                color = palette.observed, linestyle = :dot)
	side_legend!(fig, ax)
	fig
end

# ╔═╡ 3c3f7997-ca76-4536-8331-634fff7fbcb7
md"""
---

#### Adding carbon to present day atmosphere
\
``dT/dt = (1-\alpha) a - (1-\epsilon(CO_2)/2)b T^4 ``$(html"<br>")


"""

# ╔═╡ 86a2382e-0276-4787-9169-1f85f2ca1ef7
ε₀ = 0.745; # baseline emissivity

# ╔═╡ 87a384f1-1679-4f1a-aaad-ac85c117b959
T₁=((1-alpha)*a/((1-ε₀/2)*b))^(1/4)

# ╔═╡ 7a6019d9-41af-4e5c-80e6-25dc52ac1819
emissivity(CO₂,T) = ε₀+0.02 * log(CO₂/280)/log(2)+0.01*(T-T₁)

# ╔═╡ 6f1c2a8e-3b4d-4e5f-9a0b-1c2d3e4f5a63
"""
    equilibrium_temperature(CO₂; feedback = true)

Equilibrium surface temperature [K] for an atmospheric CO₂ concentration [ppm],
with or without the water-vapor feedback. It is the temperature at which the
energy budget balances, ``dT/dt = 0``, found by bisection.
"""
function equilibrium_temperature(CO₂; feedback = true)
	imbalance(T) = (1 - alpha) * a - (1 - emissivity(CO₂, feedback ? T : T₁) / 2) * b * T^4
	lo, hi = T₁ - 20, T₁ + 40
	@assert imbalance(lo) > 0 > imbalance(hi)
	for _ in 1:60
		mid = (lo + hi) / 2
		imbalance(mid) > 0 ? (lo = mid) : (hi = mid)
	end
	return (lo + hi) / 2
end

# ╔═╡ ce1792bc-36d2-49b2-bd92-351e09bb3a4f
md"""

CO₂ (ppm) = $(@bind CO₂ Slider(280:10:1120, show_value=true, default=420) )

"""

# ╔═╡ a61b1671-ad76-4a34-8d63-3f687fffe836
m5 = ODEProblem( (temp, p, t)-> a * (1-alpha) - (1-emissivity(CO₂,T₁)/2)*b*temp^4, T₁,  (0, timespan) )

# ╔═╡ 819431a7-cdcd-430a-a89a-2db90eb22e7c
let
	T_eq = equilibrium_temperature(CO₂; feedback = false)
	fig, ax = temperature_figure("CO₂ = $(CO₂) ppm"; ylims = (12.5, 16.5))
	temperature_line!(ax, solve(m5))
	reference_line!(ax, T₁; label = "initial (280 ppm): $(celsius(T₁)) °C",
	                color = palette.initial)
	reference_line!(ax, T_eq; label = "equilibrium: $(celsius(T_eq)) °C",
	                color = palette.equilibrium)
	side_legend!(fig, ax)
	fig
end

# ╔═╡ ee9724f1-5414-4c3d-85b9-e394afea2e72
md"""
---

#### Adding water vapor feedback
\
``dT/dt = (1-\alpha) a - (1-\epsilon(CO_2,T)/2)b T^4 ``$(html"<br>")


"""

# ╔═╡ 6f1c2a8e-3b4d-4e5f-9a0b-1c2d3e4f5a65
md"""
Warmer air holds more water vapor, and water vapor is itself a greenhouse gas. We model this by letting the emissivity also increase with temperature,

``\epsilon(CO_2, T) = \epsilon_0 + 0.02 \log_2(CO_2/280) + 0.01\,(T - T_1)``,

so any warming caused by CO₂ raises ``\epsilon`` further, which causes more warming: a **positive feedback**. Move the slider and compare the two curves.
"""

# ╔═╡ 6f1c2a8e-3b4d-4e5f-9a0b-1c2d3e4f5a64
md"""

CO₂ (ppm) = $(@bind CO₂_wv Slider(280:10:1120, show_value=true, default=560))

"""

# ╔═╡ 0b6e8dd2-a060-4ed9-aa03-de48e3c7c3e1
m6 = ODEProblem( (temp, p, t)-> a * (1-alpha) - (1-emissivity(CO₂_wv,temp)/2)*b*temp^4, T₁,  (0, timespan) )

# ╔═╡ 5b153580-78ee-4a73-b936-507b3b39f02c
let
	# same CO₂, emissivity frozen at T₁ (no water-vapor feedback) for comparison
	m6_nofeedback = ODEProblem((temp, p, t) -> a * (1 - alpha) -
	                           (1 - emissivity(CO₂_wv, T₁) / 2) * b * temp^4, T₁, (0, timespan))
	T_fb   = equilibrium_temperature(CO₂_wv; feedback = true)
	T_nofb = equilibrium_temperature(CO₂_wv; feedback = false)

	fig = Figure(size = (1000, 400))
	ax = Axis(fig[1, 1]; title = "CO₂ = $(CO₂_wv) ppm", xlabel = "time  [years]",
	          ylabel = "surface temperature  [°C]")
	temperature_line!(ax, solve(m6); label = "with water-vapor feedback")
	temperature_line!(ax, solve(m6_nofeedback); label = "without feedback",
	                  color = palette.nofeedback, linestyle = :dash)
	reference_line!(ax, T₁; label = "initial (280 ppm): $(celsius(T₁)) °C",
	                color = palette.initial, linestyle = :dot)
	ylims!(ax, 12.5, 19.5)
	axislegend(ax; position = :lt)

	# equilibrium warming as a function of CO₂
	CO₂s = 280:10:1120
	ΔT_fb   = [equilibrium_temperature(c; feedback = true)  - T₁ for c in CO₂s]
	ΔT_nofb = [equilibrium_temperature(c; feedback = false) - T₁ for c in CO₂s]
	ax2 = Axis(fig[1, 2]; title = "Equilibrium warming", xlabel = "CO₂  [ppm]",
	           ylabel = "ΔT  [K]", xticks = 280:140:1120)
	lines!(ax2, CO₂s, ΔT_fb; color = palette.model, label = "with water-vapor feedback")
	lines!(ax2, CO₂s, ΔT_nofb; color = palette.nofeedback, linestyle = :dash,
	       label = "without feedback")
	vlines!(ax2, CO₂_wv; color = (:black, 0.25), linewidth = 1)
	scatter!(ax2, [CO₂_wv, CO₂_wv], [T_fb - T₁, T_nofb - T₁];
	         color = [palette.model, palette.nofeedback], markersize = 12,
	         strokecolor = :white, strokewidth = 1.5)
	ylims!(ax2, -0.2, 6.5)
	axislegend(ax2; position = :lt)
	if CO₂_wv > 280
		gain = (T_fb - T₁) / (T_nofb - T₁)
		text!(ax2, CO₂_wv, T_fb - T₁; text = "  +$(round(T_fb - T₁; digits = 2)) K\n  (×$(round(gain; digits = 1)) amplification)",
		      align = (CO₂_wv > 900 ? :right : :left, :top), fontsize = 13,
		      offset = (CO₂_wv > 900 ? -8 : 0, -6))
	end
	colgap!(fig.layout, 30)
	fig
end

# ╔═╡ 4d580be7-e093-4733-89e3-6029e43d4aac
md"""
---

## Temperature as a function of latitude

Sunlight is not spread evenly over the globe: averaged over a year, the equator receives about twice as much energy per square meter as the poles. A good approximation of the annual-mean insolation at latitude ``\phi`` is

``S(\phi) = \frac{S_0}{4}\left[1 - 0.482\,P_2(\sin\phi)\right], \qquad P_2(x) = \frac{3x^2 - 1}{2}``.

If every latitude were in **local radiative balance**, with no heat carried poleward by the atmosphere and ocean,

``(1-\alpha)\,S(\phi) = \left(1 - \frac{\epsilon}{2}\right)\sigma T(\phi)^4``.

At 280 ppm the emissivity is ``\epsilon_0`` everywhere, which sets a reference temperature ``T_{ref}(\phi)`` at each latitude. Adding CO₂ raises the emissivity, and with the water-vapor feedback the local warming raises it further,

``\epsilon = \epsilon_0 + 0.02 \log_2(CO_2/280) + 0.01\,\left(T - T_{ref}(\phi)\right)``,

the same rule as in the global model, applied to each latitude's own warming.

The observed annual and zonal mean air temperature at 1000 hPa (close to sea level, so that high, cold terrain such as Antarctica does not distort the comparison) is shown for comparison.

Move the slider below to change the CO₂ concentration.
"""

# ╔═╡ 5ac215f3-4886-4b08-af24-6bc17a133ab4
begin
        "Annual-mean insolation [W/m²] at latitude φ [degrees] (North, 1975)."
        insolation(φ) = S_0 * (1 - 0.482 * (3 * sind(φ)^2 - 1) / 2)

        "Local radiative-equilibrium temperature [K] at latitude φ for 280 ppm (emissivity ε₀)."
        reference_temperature(φ) = ((1 - alpha) * insolation(φ) / ((1 - ε₀ / 2) * sigma))^(1/4)

        """
            local_equilibrium_temperature(φ, CO₂; feedback = true)

        Temperature [K] at which absorbed sunlight balances emitted radiation at
        latitude φ [degrees], with no heat transport between latitudes. The
        water-vapor feedback acts on the local warming T - T_ref(φ). The emissivity
        is kept between 0 and 1.
        """
        function local_equilibrium_temperature(φ, CO₂; feedback = true)
                Tref = reference_temperature(φ)
                ε(T) = clamp(emissivity(CO₂, feedback ? T - Tref + T₁ : T₁), 0, 1)
                imbalance(T) = (1 - alpha) * insolation(φ) - (1 - ε(T) / 2) * sigma * T^4
                lo, hi = 150.0, 400.0
                for _ in 1:60
                        mid = (lo + hi) / 2
                        imbalance(mid) > 0 ? (lo = mid) : (hi = mid)
                end
                return (lo + hi) / 2
        end
end

# ╔═╡ 6f1c2a8e-3b4d-4e5f-9a0b-1c2d3e4f5a74
md"""
CO₂ (ppm) = $(@bind CO₂_lat Slider(280:10:1120, show_value=true, default=560))
"""

# ╔═╡ 3eafff56-79c5-47a2-b8c7-2c6f6e75de1a
let
        # Observed annual and zonal mean air temperature at 1000 hPa [°C] every 5° from 90°S
        # to 90°N, which removes the cooling of high terrain (Antarctica, Greenland, Tibet):
        # NCEP/NCAR Reanalysis 1991–2020 long-term mean (NOAA PSL),
        # https://downloads.psl.noaa.gov/Datasets/ncep.reanalysis.derived/pressure/air.mon.ltm.1991-2020.nc
        φ_obs = -90:5:90
        T_obs = [
                -25.2, -22.1, -21.2, -18.4, -11.6, -5.7, 0.1, 3.4, 6.1, 9.2,
                12.7, 15.7, 18.7, 21.3, 23.3, 24.7, 25.6, 25.9, 26.0, 26.5,
                26.8, 26.6, 25.7, 24.0, 21.8, 18.8, 15.0, 10.5, 6.7, 4.0,
                1.0, -2.7, -6.3, -8.9, -11.9, -14.2, -14.2
        ]

        φ = -90:1:90
        T₀ = reference_temperature.(φ)                           # 280 ppm
        T  = [local_equilibrium_temperature(l, CO₂_lat) for l in φ]
        w  = cosd.(φ) ./ sum(cosd.(φ))                          # area weights
        ΔT = sum(w .* (T .- T₀))

        fig = Figure(size = (760, 420))
        ax = Axis(fig[1, 1]; title = "CO₂ = $(CO₂_lat) ppm:  global-mean warming $(round(ΔT; digits = 2)) K",
                  xlabel = "latitude", ylabel = "surface temperature  [°C]",
                  xticks = (-90:30:90, ["90°S", "60°S", "30°S", "0°", "30°N", "60°N", "90°N"]))
        lines!(ax, φ_obs, T_obs; color = :black, linewidth = 2.5, label = "observed at 1000 hPa (1991–2020)")
        lines!(ax, φ, T₀ .- K₀; color = palette.initial, linestyle = :dot, label = "model, 280 ppm")
        lines!(ax, φ, T .- K₀; color = palette.model, label = "model, $(CO₂_lat) ppm")
        hlines!(ax, 0; color = (:black, 0.3), linewidth = 1)
        ylims!(ax, -50, 40)
        axislegend(ax; position = :cb)
        fig
end

# ╔═╡ 6f1c2a8e-3b4d-4e5f-9a0b-1c2d3e4f5a81
md"""
---

## Temperature as a function of latitude with transport

The atmosphere and ocean carry heat from the tropics toward the poles, so each latitude is not in local radiative balance. The simplest way to represent this transport is as a meridional diffusion of temperature, which moves heat down the temperature gradient and smooths it. Writing ``x = \sin\phi``, the energy budget becomes a partial differential equation in time and latitude,

``C\,\frac{\partial T}{\partial t} = \frac{\partial}{\partial x}\left[K\,(1 - x^2)\,\frac{\partial T}{\partial x}\right] + (1-\alpha)\,S(x) - \left(1 - \frac{\epsilon}{2}\right)\sigma T^4``,

where ``K`` (in W m⁻² K⁻¹) measures the efficiency of the meridional heat transport. The gesometric factor ``1 - x^2 = \cos^2\phi`` makes the heat flux vanish at the poles, so transport only redistributes energy: it does not change the global mean. With ``K = 0`` we recover the local balance of the previous section. The water-vapor feedback is applied as before, relative to the 280 ppm state.

We solve the equation discretizing the equation in 90 latitude bands of equal area, write an ODE for the temperature of each band, and integrate with `ODEProblem` and `solve` until the temperature stops changing.
"""

# ╔═╡ 6f1c2a8e-3b4d-4e5f-9a0b-1c2d3e4f5a82
# Observed annual and zonal mean air temperature at 1000 hPa [°C] every 5° from 90°S to
# 90°N: NCEP/NCAR Reanalysis 1991–2020 long-term mean (NOAA PSL),
# https://downloads.psl.noaa.gov/Datasets/ncep.reanalysis.derived/pressure/air.mon.ltm.1991-2020.nc
observed_1000hPa = (
	φ = -90:5:90,
	T = [
		-25.2, -22.1, -21.2, -18.4, -11.6, -5.7, 0.1, 3.4, 6.1, 9.2,
		12.7, 15.7, 18.7, 21.3, 23.3, 24.7, 25.6, 25.9, 26.0, 26.5,
		26.8, 26.6, 25.7, 24.0, 21.8, 18.8, 15.0, 10.5, 6.7, 4.0,
		1.0, -2.7, -6.3, -8.9, -11.9, -14.2, -14.2
	],
)

# ╔═╡ 6f1c2a8e-3b4d-4e5f-9a0b-1c2d3e4f5a83
begin
	# grid: Nφ bands of equal area, uniform in x = sin φ
	Nφ = 90
	x_faces   = range(-1, 1; length = Nφ + 1)
	x_centers = (x_faces[1:end-1] .+ x_faces[2:end]) ./ 2
	Δx_ebm    = step(x_faces)

	"""
	    ebm_tendency!(dT, T, p, t)

	Right-hand side of the energy-balance PDE, discretized in x = sin φ: dT/dt [K/yr]
	for each band. Parameters `p = (K, CO₂, Tref)`; with `Tref = nothing` the
	emissivity is ε₀ (280 ppm reference), otherwise the water-vapor feedback acts on
	the local warming T - Tref.
	"""
	function ebm_tendency!(dT, T, p, t)
		K, CO₂, Tref = p
		for j in 1:Nφ
			# diffusive heat flux through the band edges (zero at the poles)
			F⁺ = j < Nφ ? -K * (1 - x_faces[j+1]^2) * (T[j+1] - T[j]) / Δx_ebm : 0.0
			F⁻ = j > 1  ? -K * (1 - x_faces[j]^2)   * (T[j] - T[j-1]) / Δx_ebm : 0.0
			ε = isnothing(Tref) ? ε₀ : clamp(emissivity(CO₂, T[j] - Tref[j] + T₁), 0, 1)
			S = insolation(asind(x_centers[j]))
			dT[j] = ((1 - alpha) * S - (1 - ε / 2) * sigma * T[j]^4 - (F⁺ - F⁻) / Δx_ebm) / C
		end
		return nothing
	end

	"""
	    transport_equilibrium(K, CO₂)

	Steady temperature profile [K] on the band centers for transport efficiency K
	[W m⁻² K⁻¹] and CO₂ [ppm], and the 280 ppm reference profile at the same K.
	"""
	function transport_equilibrium(K, CO₂)
		years = (0.0, 4000.0)
		Tref = solve(ODEProblem(ebm_tendency!, fill(T₁, Nφ), years, (K, 280, nothing));
		             save_everystep = false).u[end]
		T = solve(ODEProblem(ebm_tendency!, Tref, years, (K, CO₂, Tref));
		          save_everystep = false).u[end]
		return T, Tref
	end
end

# ╔═╡ 6f1c2a8e-3b4d-4e5f-9a0b-1c2d3e4f5a84
md"""
CO₂ (ppm) = $(@bind CO₂_K Slider(280:10:1120, show_value=true, default=280))

K (W m⁻² K⁻¹) = $(@bind K_diff Slider(0:0.05:1.5, show_value=true, default=0.0))
"""

# ╔═╡ 6f1c2a8e-3b4d-4e5f-9a0b-1c2d3e4f5a85
let
	T, Tref = transport_equilibrium(K_diff, CO₂_K)
	φ = asind.(x_centers)
	T_local = [local_equilibrium_temperature(l, CO₂_K) for l in φ]   # K = 0
	ΔT = sum(T .- Tref) / Nφ                                        # bands have equal area

	fig = Figure(size = (760, 420))
	ax = Axis(fig[1, 1];
	          title = "CO₂ = $(CO₂_K) ppm, K = $(K_diff) W m⁻² K⁻¹:  global-mean warming $(round(ΔT; digits = 2)) K",
	          xlabel = "latitude", ylabel = "surface temperature  [°C]",
	          xticks = (-90:30:90, ["90°S", "60°S", "30°S", "0°", "30°N", "60°N", "90°N"]))
	lines!(ax, observed_1000hPa.φ, observed_1000hPa.T; color = :black, linewidth = 2.5,
	       label = "observed at 1000 hPa (1991–2020)")
	lines!(ax, φ, T_local .- K₀; color = palette.nofeedback, linestyle = :dash,
	       label = "no transport (K = 0), $(CO₂_K) ppm")
	lines!(ax, φ, Tref .- K₀; color = palette.initial, linestyle = :dot,
	       label = "with transport, 280 ppm")
	lines!(ax, φ, T .- K₀; color = palette.model, label = "with transport, $(CO₂_K) ppm")
	hlines!(ax, 0; color = (:black, 0.3), linewidth = 1)
	ylims!(ax, -50, 40)
	axislegend(ax; position = :cb)
	fig
end

